218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
221	        String idempotencyKey = idempotencyKey();
222	        if (idempotencyKey != null) {
223	            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
224	            if (existing != null) {
225	                return new ResponseEntity<>(existing, HttpStatus.OK);
226	            }
