248	    /**
249	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
250	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
251	     * submitted address is canonicalized, the required fields and the optional postcode and
252	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
253	     * registration date is defaulted to the server date when absent and rolled forward to a business
254	     * day. The household id and identity key are derived; a create whose identity key matches an
255	     * existing, non-deleted owner is rejected with a 409 unless it opts in with {@code sharesHousehold},
256	     * and otherwise a soft-match duplicate is flagged.
257	     *
258	     * @param ownerFieldsDto the submitted owner fields
259	     * @return the normalized owner, not yet persisted
260	     */
261	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
262	        resolveAddressFields(ownerFieldsDto);
263	        validateRequiredFields(ownerFieldsDto);
264	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
265	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
266	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
267	        owner.setEmail(normalizeEmail(owner.getEmail()));
268	        validateRegistrationDate(owner.getRegistrationDate());
269	        if (owner.getRegistrationDate() == null) {
270	            owner.setRegistrationDate(LocalDate.now());
271	        }
272	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
273	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
274	        resolveHouseholdIdentity(owner, sharesHousehold);
275	        return owner;
276	    }
277	
278	    /**
279	     * Places the owner about to be created into its household and settles its identity against the
280	     * owners already on file. The owner's {@code householdId} is still derived deterministically from
281	     * its last name and postcode (it drives the household size and membership-level cap), but identity
282	     * is now decided solely by the {@code identityKey}, the SHA-256 digest over the normalized
283	     * telephone, email and the last name's Soundex code. Unless the request opted into a shared
284	     * household, an owner whose identity key matches any existing, non-deleted owner is rejected with a
285	     * 409; and, again only when the household was not opted into, a soft-match against an existing owner
286	     * flags the new owner as a possible duplicate. Two owners sharing a last name and postcode but with
287	     * different telephones now derive different identity keys, so they are admitted (as a soft match)
288	     * rather than rejected, with their membership level later capped by
289	     * {@link #applyMembershipLevelCap(Owner)}.
290	     *
291	     * @param owner the normalized owner about to be created, with its contact details already normalized
292	     * @param sharesHousehold whether the request opted into joining an existing household
293	     */
294	    private void resolveHouseholdIdentity(Owner owner, boolean sharesHousehold) {
295	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
296	        owner.setIdentityKey(buildIdentityKey(owner));
297	        if (!sharesHousehold) {
298	            rejectDuplicateIdentity(owner);
299	        }
300	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
301	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
302	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
303	    }
304	
305	    /**
306	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
307	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
308	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
309	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
310	     * registration date, measured before it is saved, which the caller uses to decide the response's
311	     * {@code bulkSignupWarning}.
312	     *
313	     * @param owner the normalized owner about to be created
314	     * @return the number of owners already registered on the owner's registration date
315	     */
316	    private long enforceCreateLimits(Owner owner) {
317	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
318	            throw new OwnerCityFullException(owner.getCity());
319	        }
320	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
321	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
322	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
323	        }
324	        return ownersRegisteredOnDay;
325	    }
326	
327	    /**
328	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
329	     * de-duplicated customer code, the number of existing namesakes, the household size once the
330	     * new owner is added, and the membership-level ceiling imposed by the household the owner joins.
331	     *
332	     * @param owner the normalized owner about to be created
333	     */
334	    private void finalizeOwnerForCreate(Owner owner) {
335	        owner.setCustomerCode(buildCustomerCode(owner));
336	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
337	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
338	        applyMembershipLevelCap(owner);
339	    }
340	
341	    /**
342	     * Caps the membership level of an owner about to be created so it cannot exceed one above the
343	     * current maximum membership level among the owner's existing household members. The owner is not
344	     * yet persisted, so {@link #activeHouseholdMembers(String)} returns exactly the members already on
345	     * file; each member's effective (already-capped) level is read via
346	     * {@link org.springframework.samples.petclinic.mapper.MembershipLevel#forOwner(Owner)}. When the
347	     * household has no existing member no ceiling applies and the cap is left unset, so the owner keeps
348	     * its fully-derived level.
349	     *
350	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
351	     */
352	    private void applyMembershipLevelCap(Owner owner) {
353	        activeHouseholdMembers(owner.getHouseholdId()).stream()
354	            .mapToInt(org.springframework.samples.petclinic.mapper.MembershipLevel::forOwner)
355	            .max()
356	            .ifPresent(maxLevel -> owner.setMembershipLevelCap(maxLevel + 1));
357	    }
358	
359	    /**
360	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
361	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
362	     * count, and adds the {@code Location} header pointing at the new owner.
363	     *
364	     * @param owner the owner that has just been saved, with its generated id populated
365	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
366	     * @return the created-owner response
367	     */
368	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
369	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
370	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
371	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
372	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
373	        emitOwnerCreatedEvent(owner, ownerDto);
374	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
375	        HttpHeaders headers = new HttpHeaders();
376	        headers.setLocation(UriComponentsBuilder.newInstance()
377	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
378	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
379	    }
380	
381	    /**
382	     * Emits the immutable, structured {@code OWNER_CREATED} audit event on the {@code AUDIT} logger,
383	     * alongside the human-readable audit line. The event is a JSON object
384	     * {@code {seq, ownerId, customerCode, membershipLevel, event}} where {@code seq} is a
385	     * process-wide, monotonically increasing sequence across all creates. Its {@code customerCode}
386	     * field carries the owner's <em>current primary identifier</em> - the customer code today, and
387	     * whatever supersedes it later (for instance the member id once the two are unified) - as
388	     * returned by {@link #primaryIdentifier(Owner)}.
389	     *
390	     * @param owner the owner that has just been saved, with its generated id populated
391	     * @param ownerDto the mapped DTO, source of the derived membership level
392	     */
393	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
394	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(),
395	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel(), "OWNER_CREATED");
396	        try {
397	            AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
398	        }
399	        catch (JacksonException e) {
400	            AUDIT.warn("failed to serialize OWNER_CREATED audit event for owner id={}", owner.getId(), e);
401	        }
402	    }
403	
404	    /**
405	     * Returns the owner's current primary identifier - the value the structured audit event carries
406	     * as its {@code customerCode}. Today that is the owner's customer code; when the customer code is
407	     * later unified into the member id, this is the single place that changes so the emitted event
408	     * carries the member id instead.
409	     *
410	     * @param owner the owner whose primary identifier is required
411	     * @return the owner's current primary identifier
412	     */
413	    private String primaryIdentifier(Owner owner) {
414	        return owner.getCustomerCode();
415	    }
416	
417	    /**
418	     * Immutable structured payload of an {@code OWNER_CREATED} audit event. The {@code customerCode}
419	     * field holds the owner's current primary identifier (see {@link #primaryIdentifier(Owner)}).
420	     */
421	    private record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode,
422	        Integer membershipLevel, String event) {
423	    }
424	
425	    /**
426	     * Canonicalizes the submitted address fields into the form that is validated, stored and
427	     * returned, before any required-field check or mapping runs. This is the single place a create
428	     * request's address input is resolved.
429	     *
430	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
431	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
432	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
433	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
434	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
435	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
436	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
437	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
438	     * that is blank only after normalization is left blank here and rejected later by
439	     * {@link #validateRequiredFields}.
440	     *
441	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
442	     */
443	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
444	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
445	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
446	        if (!line1.isEmpty()) {
447	            ownerFieldsDto.setAddressLine1(line1);
448	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
449	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
450	        }
451	        else {
452	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
453	        }
454	    }
455	
456	    /**
457	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
458	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
459	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
460	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
461	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
462	     * normalization is still rejected.
463	     *
464	     * @param ownerFieldsDto the submitted owner fields
465	     */
466	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
467	        List<String> missingFields = new ArrayList<>();
468	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
469	            missingFields.add("firstName");
470	        }
471	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
472	            missingFields.add("lastName");
473	        }
474	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
475	            missingFields.add("address");
476	        }
477	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
478	            missingFields.add("city");
479	        }
480	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
481	            missingFields.add("telephone");
482	        }
483	        if (!missingFields.isEmpty()) {
484	            throw new MissingOwnerFieldsException(missingFields);
485	        }
486	    }
487	
488	    /**
489	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
490	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
491	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
492	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
493	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
494	     * whose {@code errors} array lists {@code postcode}.
495	     *
496	     * @param postcode the submitted postcode, or {@code null} when none was supplied
497	     * @param city the owner's city, whose region determines the acceptable postcode range
498	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
499	     */
500	    private void validatePostcode(String postcode, String city) {
501	        if (!StringUtils.hasText(postcode)) {
502	            return;
503	        }
504	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
505	            throw new InvalidOwnerFieldsException(List.of("postcode"));
506	        }
507	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
508	            throw new InvalidOwnerFieldsException(List.of("postcode"));
509	        }
510	    }
511	
512	    /**
513	     * Validates an owner's optional registration date. Registration date is optional, so a missing
514	     * value is accepted (the create later defaults it to the server date). When a value is supplied
515	     * it may not lie in the future: a date later than the server's current date is rejected with a
516	     * 400 whose {@code errors} array lists {@code registrationDate}.
517	     *
518	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
519	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
520	     */
521	    private void validateRegistrationDate(LocalDate registrationDate) {
522	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
523	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
524	        }
525	    }
526	
527	    /**
528	     * Rejects a submitted owner whose derived {@code identityKey} matches that of any existing,
529	     * non-deleted owner - the same normalized telephone, email and last-name Soundex, which marks the
530	     * same person being entered twice. This single identity key is the whole of duplicate detection:
531	     * because the telephone is part of the key, distinct people who merely share a last name and
532	     * postcode (but differ in telephone) derive a different key and so are admitted rather than
533	     * rejected. Soft-deleted owners are ignored, and the email-domain blocklist has already been
534	     * applied when the email was normalized. A genuine identity collision is reported to the client as
535	     * a 409 Conflict. A request may knowingly bypass this check by opting in with
536	     * {@code sharesHousehold}, in which case it is not performed.
537	     *
538	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
539	     */
540	    private void rejectDuplicateIdentity(Owner owner) {
541	        boolean identityInUse = this.clinicService.findAllOwners().stream()
542	            .filter(existing -> !existing.isDeleted())
543	            .anyMatch(existing -> owner.getIdentityKey().equals(existing.getIdentityKey()));
544	        if (identityInUse) {
545	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
546	        }
547	    }
548	
549	    /**
550	     * Returns the owners that currently belong to the household identified by {@code householdId} -
551	     * those sharing that derived id that have not been soft-deleted. Soft-deleted owners are excluded
552	     * because they no longer count as present members, so this is the household as it stands for the
553	     * owner being created. This is the single lookup of a household's current members behind the
554	     * household checks that reason about who is already there.
555	     *
556	     * @param householdId the derived household identifier to look up
557	     * @return the existing, non-deleted owners sharing that household, in no particular order
558	     */
559	    private List<Owner> activeHouseholdMembers(String householdId) {
560	        return this.clinicService.findAllOwners().stream()
561	            .filter(existing -> !existing.isDeleted())
562	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
563	            .collect(Collectors.toList());
564	    }
565	
566	    /**
567	     * Derives the owner's {@code identityKey} as the SHA-256 hex digest over
568	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone
569	     * and email have already been normalized (the email lower-cased, or the empty string when none was
570	     * supplied) and the last name is reduced to its {@link Soundex} code. Because the normalized
571	     * telephone is part of the key, two owners who differ only in telephone derive different identity
572	     * keys, so they are not the same identity even when they share a household.
573	     *
574	     * @param owner the normalized owner about to be created, with its contact details already normalized
575	     * @return the derived identity key, as 64 lower-case hex characters
576	     */
577	    private String buildIdentityKey(Owner owner) {
578	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
579	        return Sha256.hex(owner.getTelephone() + "|" + email + "|" + Soundex.encode(owner.getLastName()));
580	    }
581	
582	    /**
583	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner whose
584	     * derived {@code identityKey} differs from an existing owner's - so it is not the same identity, and
585	     * not a 409 - yet shares that owner's last-name {@link Soundex} code and {@code postcode}. Such an
586	     * owner is still created, but is flagged as a possible duplicate of the matching owner. In
587	     * particular, two owners with the same last name and postcode but different telephones now derive
588	     * different identity keys, so instead of the old hard household-duplicate rejection they surface
589	     * here as a soft match. This is only consulted for owners that did not opt into a shared household:
590	     * an owner that declares {@code sharesHousehold} is a known household member, not a suspected
591	     * duplicate, so it is never flagged. The comparison only applies when a postcode was supplied, since
592	     * both owners must share one; when several existing owners match, the earliest (lowest id) is used.
593	     *
594	     * @param owner the normalized owner about to be created, with its {@code identityKey} already set
595	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
596	     */
597	    private Integer findPossibleDuplicate(Owner owner) {
598	        if (!StringUtils.hasText(owner.getPostcode())) {
599	            return null;
600	        }
601	        String soundex = Soundex.encode(owner.getLastName());
602	        return this.clinicService.findAllOwners().stream()
603	            .filter(existing -> !existing.isDeleted())
604	            .filter(existing -> !owner.getIdentityKey().equals(existing.getIdentityKey()))
605	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
606	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
607	            .map(Owner::getId)
608	            .filter(id -> id != null)
609	            .min(Integer::compareTo)
610	            .orElse(null);
611	    }
612	
613	    /**
614	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
615	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
616	     * address; the accepted value is lower-cased before it is stored and returned.
617	     *
618	     * @param email the raw email value submitted by the client, or {@code null}
619	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
620	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
621	     */
622	    private String normalizeEmail(String email) {
623	        if (!StringUtils.hasText(email)) {
624	            return email;
625	        }
626	        if (!EMAIL_PATTERN.matcher(email).matches()) {
627	            throw new InvalidOwnerFieldsException(List.of("email"));
628	        }
629	        String normalized = email.toLowerCase();
630	        String domain = normalized.substring(normalized.indexOf('@') + 1);
631	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
632	            throw new InvalidOwnerFieldsException(List.of("email"));
633	        }
634	        return normalized;
635	    }
636	
637	    /**
638	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
639	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
640	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
641	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
642	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
643	     *
644	     * @param owner the normalized owner about to be created
645	     * @return the assigned, de-duplicated customer code
646	     */
647	    private String buildCustomerCode(Owner owner) {
648	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
649	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
650	        return deduplicateCustomerCode(code);
651	    }
652	
653	    /**
654	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
655	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
656	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
657	     *
658	     * @param code the composed customer code, before de-duplication
659	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
660	     */
661	    private String deduplicateCustomerCode(String code) {
662	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
663	            .map(Owner::getCustomerCode)
664	            .filter(existing -> existing != null)
665	            .collect(Collectors.toSet());
666	        if (!existingCodes.contains(code)) {
667	            return code;
668	        }
669	        int suffix = 2;
670	        while (existingCodes.contains(code + "-" + suffix)) {
671	            suffix++;
672	        }
673	        return code + "-" + suffix;
674	    }
675	
676	    /**
677	     * Counts how many owners already exist that share the supplied first and last name, compared
678	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
679	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
680	     *
681	     * @param firstName the submitted owner's first name
682	     * @param lastName the submitted owner's last name
683	     * @return the number of existing owners with the same first and last name, ignoring case
684	     */
685	    private int countNamesakes(String firstName, String lastName) {
686	        return (int) this.clinicService.findAllOwners().stream()
687	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
688	                && lastName.equalsIgnoreCase(existing.getLastName()))
689	            .count();
690	    }
691	
692	    /**
693	     * Counts how many existing owners already belong to the supplied household, identified by its
694	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
695	     * owner is added (this count plus one).
696	     *
697	     * @param householdId the normalized household identifier of the owner being created
698	     * @return the number of existing owners already sharing that {@code householdId}
699	     */
700	    private int countHouseholdMembers(String householdId) {
701	        return (int) this.clinicService.findAllOwners().stream()
702	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
703	            .count();
704	    }
705	
706	    /**
707	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
708	     * enforce the per-city capacity limit when a new owner is created.
709	     *
710	     * @param city the submitted owner's city
711	     * @return the number of existing owners in that city, ignoring case
712	     */
713	    private long countOwnersInCity(String city) {
714	        return this.clinicService.findAllOwners().stream()
715	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
716	            .count();
717	    }
718	
719	    /**
720	     * Counts how many owners have already been created on the supplied registration date. Used to
721	     * enforce the per-day capacity limit when a new owner is created.
722	     *
723	     * @param registrationDate the registration date of the owner being created
724	     * @return the number of existing owners already registered on that date
725	     */
726	    /**
727	     * Rolls a registration date forward to a business day. A registration date must fall on a
728	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
729	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
730	     * returned unchanged. Every value derived from the registration date (such as the membership
731	     * number's year segment) and the daily create-limit therefore use the adjusted date.
732	     *
733	     * @param date the effective registration date, whether supplied or defaulted to the server date
734	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
735	     */
736	    private LocalDate toBusinessDay(LocalDate date) {
737	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
738	            date = date.plusDays(1);
739	        }
740	        return date;
741	    }
742	
743	    private boolean isWeekend(LocalDate date) {
744	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
745	    }
746	
747	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
748	        return this.clinicService.findAllOwners().stream()
749	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
750	            .count();
751	    }
752	
753	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
754	    @Override
755	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
756	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
757	        if (currentOwner == null) {
758	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
759	        }
760	        currentOwner.setAddress(ownerFieldsDto.getAddress());
761	        currentOwner.setCity(ownerFieldsDto.getCity());
762	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
763	        currentOwner.setLastName(ownerFieldsDto.getLastName());
764	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
765	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
766	        this.clinicService.saveOwner(currentOwner);
767	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
768	    }
769	
770	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
771	    @Transactional
772	    @Override
773	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
774	        Owner owner = this.clinicService.findOwnerById(ownerId);
775	        if (owner == null) {
776	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
777	        }
778	        owner.setDeleted(true);
779	        this.clinicService.saveOwner(owner);
780	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
781	    }
782	
783	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
784	    @Override
785	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
786	        Owner owner = this.clinicService.findOwnerById(ownerId);
787	        if (owner == null) {
788	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
789	        }
790	        HttpHeaders headers = new HttpHeaders();
791	        Pet pet = petMapper.toPet(petFieldsDto);
792	        owner.setId(ownerId);
793	        pet.setOwner(owner);
794	        pet.getType().setName(null);
795	        this.clinicService.savePet(pet);
796	        PetDto petDto = petMapper.toPetDto(pet);
797	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
798	            .buildAndExpand(pet.getId()).toUri());
799	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
800	    }
801	
802	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
803	    @Override
804	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
805	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
806	        if (currentOwner != null) {
807	            Pet currentPet = this.clinicService.findPetById(petId);
808	            if (currentPet != null) {
809	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
810	                currentPet.setName(petFieldsDto.getName());
811	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
812	                this.clinicService.savePet(currentPet);
813	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
814	            }
815	        }
816	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
817	    }
818	
819	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
820	    @Override
821	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
822	        HttpHeaders headers = new HttpHeaders();
823	        Visit visit = visitMapper.toVisit(visitFieldsDto);
824	        Pet pet = new Pet();
825	        pet.setId(petId);
826	        visit.setPet(pet);
827	        this.clinicService.saveVisit(visit);
828	        VisitDto visitDto = visitMapper.toVisitDto(visit);
829	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
830	            .buildAndExpand(visit.getId()).toUri());
831	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
832	    }
833	
834	
835	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
836	    @Override
837	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
838	        Owner owner = this.clinicService.findOwnerById(ownerId);
839	        if (owner != null) {
840	            Pet pet = owner.getPet(petId);
841	            if (pet != null) {
842	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
843	            }
844	        }
845	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
846	    }
847	}
